// Intent Classifier — build the OpenAI request (Code node).
// Input : webhook body { query, session_id?, website_url }
// Output: { query, session_id, website_url, oai_body }
const body = $input.first().json.body || $input.first().json || {};
const query = String(body.query || '').trim();
if (!query) throw new Error('query is required');

const sys = [
  'Classify a dental/orthodontic clinic chatbot query into one or more intents.',
  'Intents: "pricing" (cost/price/insurance questions), "services" (treatments, FAQs, general dental/ortho questions),',
  '"general" (clinic info: doctors, location, contact, policies, about), "booking" (scheduling/appointment requests).',
  'A query can match multiple intents. Return ONLY JSON:',
  '{ "intents": [ { "name": "pricing"|"services"|"general"|"booking", "confidence": 0.0-1.0 } ] }',
  'Include only intents that are plausibly relevant; omit ones that clearly do not apply.',
  'If the query is unrelated to a dental/orthodontic clinic (e.g. general trivia, unrelated topics), return { "intents": [] }.',
].join('\n');

return [{
  json: {
    query, session_id: body.session_id || null, website_url: body.website_url,
    oai_body: {
      model: 'gpt-4o-mini',
      temperature: 0,
      response_format: { type: 'json_object' },
      messages: [
        { role: 'system', content: sys },
        { role: 'user', content: query },
      ],
    },
  },
}];

// Router + Parallel Executor — n8n Code node (Run Once for All Items).
// Parses the classifier's intents, fans out to the relevant sub-agent
// webhooks CONCURRENTLY via Promise.all (true parallel execution, not
// sequential HTTP nodes), and tolerates partial failures (one agent
// erroring/timing out does not fail the whole request).
const helpers = this.helpers;
const CONFIDENCE_THRESHOLD = 0.4;
const AGENT_TIMEOUT_MS = 60000;
const BASE = 'http://localhost:5678/webhook/';
const AGENT_PATHS = {
  pricing: 'agent/pricing',
  services: 'agent/services-faq',
  general: 'agent/general',
  booking: 'agent/booking',
};

const cls = $('ClassifyIntent').first().json;
const query = cls.query;
const session_id = cls.session_id;
const website_url = cls.website_url;

let intents = [];
try { intents = (JSON.parse($input.first().json.choices[0].message.content).intents) || []; } catch (e) { intents = []; }
const routed = intents.filter(function (i) { return i && AGENT_PATHS[i.name] && i.confidence >= CONFIDENCE_THRESHOLD; });

async function callAgent(name, path) {
  try {
    let res = await helpers.httpRequest({
      method: 'POST', url: BASE + path,
      body: { query, website_url, session_id }, json: true, timeout: AGENT_TIMEOUT_MS,
    });
    // Sub-agent webhooks respond with responseData:'allEntries', so the raw
    // body is a JSON array of items (n8n's dedicated HTTP Request node
    // auto-unwraps this; helpers.httpRequest called from a Code node does not).
    if (Array.isArray(res)) res = res[0] || {};
    return { intent: name, ok: true, ...res };
  } catch (e) {
    return { intent: name, ok: false, error: String((e && e.message) || e) };
  }
}

let results;
let usedFallback = false;
if (routed.length === 0) {
  usedFallback = true;
  results = [{
    intent: 'fallback', ok: true, grounded: false,
    answer: "I'm not sure I can help with that from what I know about this clinic. Could you rephrase, or ask about services, pricing, hours, or booking an appointment?",
  }];
} else {
  results = await Promise.all(routed.map(function (r) { return callAgent(r.name, AGENT_PATHS[r.name]); }));
}

return [{
  json: {
    query, session_id, website_url,
    intents: intents,
    routed: routed.map(function (r) { return r.name; }),
    used_fallback: usedFallback,
    agent_results: results,
  },
}];

// Response Merger — n8n Code node (Run Once for All Items).
// Collects the parallel sub-agent outputs into one deduped context bundle.
// Input : RouteAndCall's output { query, agent_results[], used_fallback, ... }
const d = $input.first().json;
const results = d.agent_results || [];

const seen = new Set();
const answers = [];
let any_grounded = false;
for (const r of results) {
  if (!r || !r.answer) continue;
  const key = r.answer.trim().toLowerCase();
  if (seen.has(key)) continue;
  seen.add(key);
  if (r.grounded) any_grounded = true;
  answers.push({ intent: r.intent, grounded: !!r.grounded, text: r.answer });
}

return [{
  json: {
    query: d.query, session_id: d.session_id, website_url: d.website_url,
    intents: d.intents, routed: d.routed, used_fallback: d.used_fallback,
    any_grounded,
    answers,
  },
}];

// Synthesizer request builder — n8n Code node.
// Merges the (already-grounded-safe) sub-agent answers into ONE professional
// reply. If no sub-agent ran (used_fallback) or produced an answer, skip the
// LLM call entirely and pass the safe deflection straight through - never
// hand a fully-unrelated query to a "make it sound nice" pass.
const d = $input.first().json;

if (d.used_fallback || d.answers.length === 0) {
  return [{
    json: {
      query: d.query, session_id: d.session_id,
      skip_llm: true,
      final_answer: (d.answers[0] && d.answers[0].text) ||
        "I'm not sure I can help with that from what I know about this clinic. Could you ask about services, pricing, hours, or booking an appointment?",
    },
  }];
}

const bundle = d.answers.map(function (a, i) {
  return '[' + (i + 1) + '] (' + a.intent + (a.grounded ? '' : ', not grounded') + ') ' + a.text;
}).join('\n\n');

const sys = [
  'You are the front-desk voice/chat assistant for a dental/orthodontic clinic.',
  'Combine the sub-agent answers below into ONE natural, warm, professional reply to the patient.',
  'Do not add any fact not present in the sub-agent answers. Do not repeat the same point twice.',
  'If some answers say information is unavailable, acknowledge that briefly rather than glossing over it.',
  'Keep it concise (<= 100 words), no bullet points, no citation markers - just plain conversational text suitable for text-to-speech.',
].join('\n');

const user = 'PATIENT QUESTION: ' + d.query + '\n\nSUB-AGENT ANSWERS:\n' + bundle;

return [{
  json: {
    query: d.query, session_id: d.session_id,
    skip_llm: false,
    oai_body: {
      model: 'gpt-4o',
      temperature: 0.3,
      messages: [
        { role: 'system', content: sys },
        { role: 'user', content: user },
      ],
    },
  },
}];

// Finalize — runs after either the Synthesizer OpenAI call or the skip-LLM
// passthrough. Produces the orchestrator's single response shape.
// Node name tells us which branch ran (IsSkipLLM routes here from both sides).
const d = $('BuildSynthesisReq').first().json;
const merged = $('MergeResults').first().json;

let reply;
if (d.skip_llm) {
  reply = d.final_answer;
} else {
  try { reply = $input.first().json.choices[0].message.content.trim(); }
  catch (e) { reply = (merged.answers[0] && merged.answers[0].text) || "I'm not sure - please contact the clinic directly."; }
}

return [{
  json: {
    reply,
    session_id: d.session_id,
    intents: merged.intents,
    routed: merged.routed,
    grounded: merged.any_grounded,
    sources: merged.answers.map(function (a) { return { intent: a.intent, grounded: a.grounded }; }),
  },
}];

// Finalize — runs after either the Synthesizer OpenAI call or the skip-LLM
// passthrough. Produces the orchestrator's single response shape.
// Node name tells us which branch ran (IsSkipLLM routes here from both sides).
const d = $('BuildSynthesisReq').first().json;
const merged = $('MergeResults').first().json;

let reply;
if (d.skip_llm) {
  reply = d.final_answer;
} else {
  try { reply = $input.first().json.choices[0].message.content.trim(); }
  catch (e) { reply = (merged.answers[0] && merged.answers[0].text) || "I'm not sure - please contact the clinic directly."; }
}

return [{
  json: {
    reply,
    session_id: d.session_id,
    intents: merged.intents,
    routed: merged.routed,
    grounded: merged.any_grounded,
    sources: merged.answers.map(function (a) { return { intent: a.intent, grounded: a.grounded }; }),
  },
}];
